// n8n Code Node (First one - Grouping by City)
const itemsData = $input.all();
const groupedCities = {};

for (const item of itemsData) {
  const data = item.json;
  const city = (data.city || "Unknown").trim().toLowerCase();

  if (!groupedCities[city]) {
    groupedCities[city] = {
      city: city,
      contacts: []
    };
  }
  groupedCities[city].contacts.push(data);
}

// Output the grouped data
return Object.values(groupedCities).map(cityGroup => {
  return { json: cityGroup };
});

// Safely loop over all weather items
const weatherItems = $input.all();
const contactsData = $('Group Contacts by City').all();
const results = [];

const seasonalSettings = {
  0:  { heat: 70, cold: 25 }, // Jan
  1:  { heat: 75, cold: 28 }, // Feb
  2:  { heat: 80, cold: 32 }, // Mar
  3:  { heat: 82, cold: 34 }, // Apr
  4:  { heat: 85, cold: 36 }, // May
  5:  { heat: 90, cold: 40 }, // Jun
  6:  { heat: 95, cold: 45 }, // Jul
  7:  { heat: 95, cold: 45 }, // Aug
  8:  { heat: 90, cold: 40 }, // Sep
  9:  { heat: 85, cold: 34 }, // Oct
  10: { heat: 80, cold: 30 }, // Nov
  11: { heat: 75, cold: 25 }  // Dec
};

for (const item of weatherItems) {
  const weatherData = item.json;

  // Safety Check: Verify weather object has the expected structure
  if (!weatherData || !weatherData.location || !weatherData.forecast) {
    continue;
  }

  const cityName = weatherData.location.name.toLowerCase();
  let cityContacts = [];

  // Find contacts for this city from the grouped data
  for (const contactGroup of contactsData) {
    if (contactGroup.json.city && contactGroup.json.city.toLowerCase() === cityName) {
      cityContacts = contactGroup.json.contacts;
      break;
    }
  }

  // Skip if no matching contacts found
  if (cityContacts.length === 0) continue;

  // Extract current month for seasonal threshold
  const forecastDate = new Date(weatherData.location.localtime);
  const currentMonth = forecastDate.getMonth(); 

  const HEATWAVE_THRESHOLD = seasonalSettings[currentMonth].heat;
  const FREEZE_THRESHOLD = seasonalSettings[currentMonth].cold;

  let isExtremeWeatherComing = false;
  let weatherEventDetails = { type: null, targetDate: "", expectedTemp: null };

  // Check forecast for extreme weather
  const forecastDays = weatherData.forecast.forecastday;
  for (const day of forecastDays) {
    // Check Heat
    if (day.day.maxtemp_f >= HEATWAVE_THRESHOLD) {
      isExtremeWeatherComing = true;
      weatherEventDetails.type = 'HEATWAVE';
      weatherEventDetails.targetDate = day.date;
      weatherEventDetails.expectedTemp = day.day.maxtemp_f;
      break; 
    }
    // Check Cold/Snow
    else if (day.day.mintemp_f <= FREEZE_THRESHOLD || day.day.daily_will_it_snow === 1) {
      isExtremeWeatherComing = true;
      weatherEventDetails.type = 'FREEZE';
      weatherEventDetails.targetDate = day.date;
      weatherEventDetails.expectedTemp = day.day.mintemp_f;
      break; 
    }
  }

  // Add mapped data to results if an event is detected
  if (isExtremeWeatherComing) {
    for (const contact of cityContacts) {
      results.push({
        json: {
          contactId: contact.id || null,
          email: contact.email || null,
          phone: contact.phone || null,
          city: weatherData.location.name,
          trigger_date: weatherEventDetails.targetDate,
          expected_temp: weatherEventDetails.expectedTemp,
          campaign_type: weatherEventDetails.type,
          threshold_used: weatherEventDetails.type === 'HEATWAVE' ? HEATWAVE_THRESHOLD : FREEZE_THRESHOLD
        }
      });
    }
  }
}

return results;
